window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1e34d31c7f1de285"]={"versions": [{"id": "FIG-1e34d31c7f1de285", "releases": ["R2.1.20", "R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing-Diagramm mit korrespondierender Wertetabelle im Kontext des AUTOSAR-Treibers für die Input Capture Unit (ICU Driver), angesiedelt im Microcontroller Abstraction Layer (MCAL). Das Diagramm illustriert das Funktionsprinzip der Zeitstempelerfassung (Timestamping) an digitalen Eingangskanälen bezogen auf einen hardwarebasierten Freilauftimer.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Timestamp Timer / Timstamp Timer</strong>: Freilaufender Hardware-Zähler mit 16-Bit-Wertebereich (<code>0</code> bis <code>0xFFFF</code>), der kontinuierlich inkrementiert und bei Erreichen des Maximalwerts überläuft (Wrap-around).\n</li><li><strong>Input Signal</strong>: Digitales Eingangssignal am ICU-Kanal mit den diskreten Pegeln <code>Low</code> und <code>High</code>.\n</li><li><strong>Wertetabelle (Input Signal Level / Timestamp Timer)</strong>: Zuordnung der detektierten Signalflanken bzw. Signalzustände zu den exakten diskreten Zählerständen des Timers zum Erfassungszeitpunkt.\n</li><li><strong>Zeitachse <code>t</code></strong>: Horizontale Referenzachse für den zeitlichen Ablauf von Zähler und Signalflanken.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Timer startet bei <code>0</code> und läuft kontinuierlich linear hoch.\n</li><li>Das Eingangssignal wechselt zwischen <code>Low</code> und <code>High</code>, wobei jede aktive Flanke (steigend und fallend) erfasst wird.\n</li><li>Bei jeder Signalflanke wird der momentane Timer-Wert im Zeitstempel-Puffer abgelegt:\n<ul class=\"fig-list\"><li>Steigende Flanke auf <code>High</code>: Zählerstand <code>5461</code>\n</li><li>Fallende Flanke auf <code>Low</code>: Zählerstand <code>10922</code>\n</li><li>Steigende Flanke auf <code>High</code>: Zählerstand <code>22937</code>\n</li><li>Fallende Flanke auf <code>Low</code>: Zählerstand <code>32767</code>\n</li><li>Steigende Flanke auf <code>High</code>: Zählerstand <code>43690</code>\n</li><li>Fallende Flanke auf <code>Low</code>: Zählerstand <code>49151</code>\n</li><li>Steigende Flanke auf <code>High</code>: Zählerstand <code>58981</code>\n</li></ul>\n</li><li>Zwischen den Zeitstempeln <code>58981</code> und <code>6553</code> erreicht der Timer seinen Maximalwert <code>0xFFFF</code> und läuft auf <code>0</code> über (Timer-Overflow / Wrap-around).\n</li><li>Nach dem Überlauf werden nachfolgende Flanken fortlaufend mit den neuen Timer-Werten registriert:\n<ul class=\"fig-list\"><li>Fallende Flanke auf <code>Low</code>: Zählerstand <code>6553</code>\n</li><li>Steigende Flanke auf <code>High</code>: Zählerstand <code>16383</code>\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der Treiber muss in der Lage sein, Zeitstempel sowohl bei steigenden als auch bei fallenden Flanken konsistent zu erfassen (konfigurierbare Flankenerkennung für beide Flankenrichtungen).\n</li><li>Software-Schichten oberhalb des Treibers (oder der ICU-Treiber selbst bei Berechnungen von Zeitdifferenzen / Periodendauern) müssen den Überlauf des 16-Bit-Timers (<code>0xFFFF -&gt; 0</code>) bei Differenzbildungen durch Modulo-Arithmetik (<code>(uint16)(t2 - t1)</code>) korrekt handhaben.\n</li><li>Die Zeitstempelwerte spiegeln den exakten Hardware-Abtastzeitpunkt wider und erfordern jitterarme Erfassung über Hardware-Capture-Register.\n</li></ul>"}, {"id": "FIG-e4f96beffff06d10", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing-Diagramm mit korrespondierender Wertetabelle im Kontext des AUTOSAR-Treibers für die Input Capture Unit (ICU Driver), angesiedelt im Microcontroller Abstraction Layer (MCAL). Das Diagramm illustriert das Funktionsprinzip der Zeitstempelerfassung (Timestamping) an digitalen Eingangskanälen bezogen auf einen hardwarebasierten Freilauftimer.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Timestamp Timer / Timstamp Timer</strong>: Freilaufender Hardware-Zähler mit 16-Bit-Wertebereich (<code>0</code> bis <code>0xFFFF</code>), der kontinuierlich inkrementiert und bei Erreichen des Maximalwerts überläuft (Wrap-around).\n</li><li><strong>Input Signal</strong>: Digitales Eingangssignal am ICU-Kanal mit den diskreten Pegeln <code>Low</code> und <code>High</code>.\n</li><li><strong>Wertetabelle (Input Signal Level / Timestamp Timer)</strong>: Zuordnung der detektierten Signalflanken bzw. Signalzustände zu den exakten diskreten Zählerständen des Timers zum Erfassungszeitpunkt.\n</li><li><strong>Zeitachse <code>t</code></strong>: Horizontale Referenzachse für den zeitlichen Ablauf von Zähler und Signalflanken.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Timer startet bei <code>0</code> und läuft kontinuierlich linear hoch.\n</li><li>Das Eingangssignal wechselt zwischen <code>Low</code> und <code>High</code>, wobei jede aktive Flanke (steigend und fallend) erfasst wird.\n</li><li>Bei jeder Signalflanke wird der momentane Timer-Wert im Zeitstempel-Puffer abgelegt:\n<ul class=\"fig-list\"><li>Steigende Flanke auf <code>High</code>: Zählerstand <code>5461</code>\n</li><li>Fallende Flanke auf <code>Low</code>: Zählerstand <code>10922</code>\n</li><li>Steigende Flanke auf <code>High</code>: Zählerstand <code>22937</code>\n</li><li>Fallende Flanke auf <code>Low</code>: Zählerstand <code>32767</code>\n</li><li>Steigende Flanke auf <code>High</code>: Zählerstand <code>43690</code>\n</li><li>Fallende Flanke auf <code>Low</code>: Zählerstand <code>49151</code>\n</li><li>Steigende Flanke auf <code>High</code>: Zählerstand <code>58981</code>\n</li></ul>\n</li><li>Zwischen den Zeitstempeln <code>58981</code> und <code>6553</code> erreicht der Timer seinen Maximalwert <code>0xFFFF</code> und läuft auf <code>0</code> über (Timer-Overflow / Wrap-around).\n</li><li>Nach dem Überlauf werden nachfolgende Flanken fortlaufend mit den neuen Timer-Werten registriert:\n<ul class=\"fig-list\"><li>Fallende Flanke auf <code>Low</code>: Zählerstand <code>6553</code>\n</li><li>Steigende Flanke auf <code>High</code>: Zählerstand <code>16383</code>\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der Treiber muss in der Lage sein, Zeitstempel sowohl bei steigenden als auch bei fallenden Flanken konsistent zu erfassen (konfigurierbare Flankenerkennung für beide Flankenrichtungen).\n</li><li>Software-Schichten oberhalb des Treibers (oder der ICU-Treiber selbst bei Berechnungen von Zeitdifferenzen / Periodendauern) müssen den Überlauf des 16-Bit-Timers (<code>0xFFFF -&gt; 0</code>) bei Differenzbildungen durch Modulo-Arithmetik (<code>(uint16)(t2 - t1)</code>) korrekt handhaben.\n</li><li>Die Zeitstempelwerte spiegeln den exakten Hardware-Abtastzeitpunkt wider und erfordern jitterarme Erfassung über Hardware-Capture-Register.\n</li></ul>"}], "trans": [{"from": "FIG-1e34d31c7f1de285", "to": "FIG-e4f96beffff06d10", "fr": "R3.0.7", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
